={{ (() => {
  const row = $('Get SerpApi Circuit (Research)').first()?.json || {};
  if (row.provider !== 'serpapi_account_2' || $json.can_research_company !== true ||
      !String($json.prospect_research_query || '').trim()) return false;
  // A provider error anywhere in this research run disables further search calls.
  if ($('Recover Research Context').isExecuted) return false;
  const failed = Number(row.last_failure_code || 0) !== 0;
  if (!failed) return true;
  const until = Date.parse(row.cooldown_until || '');
  if (!Number.isFinite(until) || Date.now() < until) return false;
  return !$('Claim Research Recovery Lease').isExecuted;
})() }}

